<script setup lang="ts">
import { dateLabel, isArchived, projectName, recordTypes, timeLabel } from '../api'
import { Image, MapPin } from 'lucide-vue-next'
import type { Attachment, RecordEntry } from '../types'
defineProps<{records:RecordEntry[];showDate?:boolean;selectable?:boolean;selected?:string[]}>()
const emit=defineEmits<{image:[attachment:Attachment,images:Attachment[]];edit:[record:RecordEntry];toggle:[id:string]}>()
</script>
<template><ol class="timeline"><li v-for="record in records" :key="record.id" class="timeline-item"><div class="timeline-time"><input v-if="selectable" type="checkbox" :checked="selected?.includes(record.id)" :disabled="isArchived(record.project_id)" :aria-label="`选择记录 ${record.title||record.code}`" @change="emit('toggle',record.id)"/><span v-if="showDate">{{dateLabel(record.occurred_at||record.created_at)}}</span><strong>{{timeLabel(record.occurred_at||record.created_at)}}</strong></div><div class="timeline-dot"/><article class="timeline-content"><div class="record-meta"><span class="badge" :class="record.type">{{recordTypes[record.type]||record.type}}</span><span>{{projectName(record.project_id)}}</span><span v-if="record.code" class="record-code">{{record.code}}</span></div><h3 v-if="record.title"><button class="table-title" @click="emit('edit',record)">{{record.title}}</button></h3><p class="record-content">{{record.content}}</p><div class="record-images" v-if="record.attachments?.length"><template v-for="attachment in record.attachments" :key="attachment.id"><button v-if="attachment.mime?.startsWith('image/')" class="image-thumb" :aria-label="`查看图片 ${attachment.filename}`" @click="emit('image',attachment,record.attachments.filter(a=>a.mime?.startsWith('image/')))"><img :src="attachment.thumb_url||attachment.url||`/api/attachments/${attachment.id}`" :alt="attachment.filename" loading="lazy"/></button><a v-else class="attachment-link" :href="`/api/attachments/${attachment.id}`" :download="attachment.filename"><Image :size="14"/>{{attachment.filename}}</a></template></div><div class="record-bottom"><span v-if="record.location" class="location"><MapPin :size="13"/>{{record.location}}</span><span v-for="tag in record.tags" :key="tag" class="tag">#{{tag}}</span><button class="text-button" @click="emit('edit',record)">查看详情</button></div></article></li></ol></template>
